() => {
  document.documentElement.style.zoom = '';
  const btn = Array.from(document.querySelectorAll('button')).find(b => (b.textContent||'').includes('深度分析'));
  if (!btn) return 'not found';
  // find scrollable ancestors
  let el = btn.parentElement; const scrollables = [];
  while (el) {
    if (el.scrollWidth > el.clientWidth + 2) scrollables.push({ tag: el.tagName, cls: (el.className||'').toString().slice(0,60), sw: el.scrollWidth, cw: el.clientWidth });
    el = el.parentElement;
  }
  return scrollables;
}

