() => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => (b.textContent||'').includes('深度分析'));
  let el = btn.parentElement;
  while (el && !(el.scrollWidth > el.clientWidth + 2 && (el.className||'').toString().includes('overflow-x-auto'))) el = el.parentElement;
  if (!el) return 'container not found';
  el.scrollLeft = el.scrollWidth;
  const r1 = btn.getBoundingClientRect();
  const btn2 = Array.from(document.querySelectorAll('button')).find(b => (b.textContent||'').includes('先制定计划'));
  const r2 = btn2.getBoundingClientRect();
  return { deep: {x: Math.round(r1.x), right: Math.round(r1.right)}, plan: {x: Math.round(r2.x), right: Math.round(r2.right)}, scrollLeft: el.scrollLeft };
}

() => {
