}

() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const ppt = btns.find(b => (b.textContent||'').includes('下载 PPT 简报'));
  const pdf = btns.find(b => (b.textContent||'').includes('导出高清 PDF 文档'));
  const info = (b) => { if (!b) return null; const cs = getComputedStyle(b); return { text: b.textContent.trim(), background: cs.backgroundImage || cs.background, backgroundColor: cs.backgroundColor, color: cs.color }; };
  return { ppt: info(ppt), pdf: info(pdf) };
}

