() => {
  window.__downloadLog = [];
  const origCreate = document.createElement.bind(document);
  document.createElement = function(tag, ...args) {
    const el = origCreate(tag, ...args);
    if (tag.toLowerCase() === 'a') {
      const origClick = el.click.bind(el);
      el.click = function() {
        window.__downloadLog.push({ tag: 'a', href: (el.href||'').slice(0,80), download: el.download });
        return origClick();
      };
    }
    return el;
  };
  const origAssign = URL.createObjectURL.bind(URL);
  URL.createObjectURL = function(blob) {
    const u = origAssign(blob);
    window.__downloadLog.push({ blobUrl: u, size: blob && blob.size });
    return u;
  };
  return 'hooks installed';
}
